script:
(function () {
  'use strict';
  // Investment distributions: a withdrawal schedule from one portfolio by one of three methods.
  //   Growth: the annual return is applied monthly at the equivalent rate j = (1 + r)^(1/12) - 1.
  //   Each distribution is taken at the start of its period (monthly, quarterly or yearly), then the
  //   remaining balance grows; a distribution never exceeds the balance left.
  //   Fixed amount: the same amount every period, optionally raised by inflation once a year.
  //   Fixed percent: each year's total = start-of-year balance x percent, paid in equal parts.
  //   Required minimum: each year's total = start-of-year balance / IRS Uniform Lifetime Table
  //   divisor for the age reached that year (none before the chosen start age), paid in equal parts.
  // Checked in Node (aq5/tests/dx.test.js): $500,000, 5%, $30,000 yearly for 10 years matches the
  // closed form B0(1+r)^n - W(1+r)((1+r)^n - 1)/r = $425,215.25; 4% fixed yearly for 10 years =
  // 500,000 x (0.96 x 1.05)^10 = $541,471.15 (balance never runs out); 0% return with $1,000 monthly
  // from $10,000 runs out after 10 months; RMD at 73 on $300,000 = 300,000 / 26.5 = $11,320.75 and at
  // 75 on $100,000 = $4,065.04 (same as the live RMD calculator); no RMD before the start age.
  // ---- IRS required minimum distribution divisors -----------------------------------------
  // Uniform Lifetime Table: IRS Publication 590-B (2025), Appendix B, Table III, in effect for
  // distribution years 2022 and later, still used for 2026. Key = age reached in the year.
  // Checked against the Pub. 590-B text. Ages 120 and over use 2.0.
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // RMD start age (SECURE 2.0 Act): 73 if born 1951-1959, 75 if born 1960 or later.
  // -------------------------------------------------------------------------------------------

  // --- calc start
  function divisor(age) {
    if (age >= 120) return UNIFORM_TABLE[120];
    return UNIFORM_TABLE[age] || 0;
  }

  // o: { balance, rate, method: 'amount'|'percent'|'rmd', amount, freq, percent, age, rmdStart,
  //      years, inflation, adjust }
  function schedule(o) {
    var j = Math.pow(1 + o.rate, 1 / 12) - 1, step = 12 / o.freq;
    var bal = o.balance, rows = [], total = 0, depleted = 0, perPeriod = o.amount;
    for (var y = 1; y <= o.years; y++) {
      var age = o.age + y - 1, start = bal, yearTotal = 0, div = 0, pay;
      if (o.method === 'amount') {
        pay = perPeriod;
        if (o.adjust) perPeriod = perPeriod * (1 + o.inflation);
      } else if (o.method === 'percent') {
        pay = start * o.percent / o.freq;
      } else {
        div = age >= o.rmdStart ? divisor(age) : 0;
        pay = div ? start / div / o.freq : 0;
      }
      var growth = 0;
      for (var m = 0; m < 12; m++) {
        if (m % step === 0) {
          var w = Math.min(bal, pay);
          bal -= w; yearTotal += w;
        }
        var g = bal * j;
        bal += g; growth += g;
      }
      if (bal < 0.005) bal = 0;
      total += yearTotal;
      rows.push({ year: y, age: age, start: start, paid: yearTotal, growth: growth, end: bal, divisor: div });
      if (!depleted && bal === 0 && start > 0 && yearTotal > 0) depleted = y;
      if (bal === 0) break;
    }
    return { rows: rows, total: total, end: bal, depleted: depleted };
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var OUTPUTS = ['dxFirstYear', 'dxTotal', 'dxEndBalance', 'dxLasts', 'dxFirstPeriod', 'dxRateDrawn', 'dxGrowthTotal'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function method() {
    var r = document.querySelector('input[name="dxMethod"]:checked');
    return r ? r.value : 'amount';
  }

  function fail(msg) {
    var error = document.getElementById('dxError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { set(id, '–'); });
    document.getElementById('dxSchedule').innerHTML = '';
    document.getElementById('dxNote').hidden = true;
  }

  function update() {
    var m = method();
    document.getElementById('dxAmountBox').hidden = m !== 'amount';
    document.getElementById('dxPercentBox').hidden = m !== 'percent';
    document.getElementById('dxRmdBox').hidden = m !== 'rmd';
    document.getElementById('dxInflBox').hidden = m !== 'amount';
    document.getElementById('dxError').hidden = true;

    var o = {
      balance: num('dxBalance'), rate: num('dxRate') / 100, method: m, amount: num('dxAmount'),
      freq: parseInt(document.getElementById('dxFreq').value, 10), percent: num('dxPercent') / 100,
      age: Math.round(num('dxAge')), rmdStart: parseInt(document.getElementById('dxRmdStart').value, 10),
      years: Math.round(num('dxYears')), inflation: num('dxInflation') / 100,
      adjust: document.getElementById('dxAdjust').checked
    };
    if ([o.balance, o.rate, o.age, o.years].some(isNaN) || o.balance < 0 || o.rate < -0.5 || o.rate > 0.3 ||
        o.age < 0 || o.age > 120 || o.years < 1 || o.years > 60) {
      return fail('Enter a non-negative balance, a return from -50% to 30%, an age from 0 to 120 and 1 to 60 years.');
    }
    if (m === 'amount' && (isNaN(o.amount) || o.amount < 0 || isNaN(o.inflation) || o.inflation < 0 || o.inflation > 0.2)) {
      return fail('Enter a non-negative distribution amount and an inflation rate from 0% to 20%.');
    }
    if (m === 'percent' && (isNaN(o.percent) || o.percent < 0 || o.percent > 1)) {
      return fail('Enter a yearly distribution rate from 0% to 100%.');
    }
    var r = schedule(o);
    var first = r.rows[0], growthTotal = r.rows.reduce(function (a, row) { return a + row.growth; }, 0);
    var periodName = { 12: 'month', 4: 'quarter', 1: 'year' }[o.freq];
    set('dxFirstYear', money.format(first.paid));
    set('dxFirstPeriod', first.paid > 0 ? money.format(first.paid / o.freq) + ' a ' + periodName : '$0');
    set('dxTotal', money.format(r.total));
    set('dxEndBalance', money.format(r.end));
    set('dxGrowthTotal', money.format(growthTotal));
    set('dxRateDrawn', first.start > 0 ? (first.paid / first.start * 100).toFixed(2) + '%' : '–');
    set('dxLasts', o.balance === 0 ? '–' : r.depleted ? 'Runs out in year ' + r.depleted : 'Lasts all ' + o.years + ' years');
    var note = document.getElementById('dxNote');
    if (m === 'rmd' && first.paid === 0) {
      note.hidden = false;
      note.textContent = 'No required minimum applies until age ' + o.rmdStart + ', so the early years show no distributions.';
    } else if (r.depleted) {
      note.hidden = false;
      note.textContent = 'At these assumptions the portfolio is used up in year ' + r.depleted +
        (o.age ? ' (age ' + (o.age + r.depleted - 1) + ').' : '.');
    } else {
      note.hidden = true;
    }
    document.getElementById('dxSchedule').innerHTML = r.rows.map(function (row) {
      var drawn = row.start > 0 ? (row.paid / row.start * 100).toFixed(2) + '%' : '–';
      return '<tr><td>' + row.year + '</td><td>' + row.age + '</td><td>' + money.format(row.start) + '</td><td>' +
             money.format(row.paid) + '</td><td>' + drawn + '</td><td>' + money.format(row.growth) + '</td><td>' +
             money.format(row.end) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('dxForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
